"""Full discrete logs in F(2^18)* at m = 37, built on tools/census37.py's basis machinery."""
import sys, os, functools
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'tools'))
import numpy as np
import census37 as C
from census37 import F, M, coord, _basis, characters
N18 = 2**18 - 1

@functools.cache
def element_of_coord(c):
    v = 0
    for i, (_, row) in enumerate(_basis()):
        if c >> i & 1:
            v ^= row
    return v

@functools.cache
def generator():
    g = next(v for v in map(element_of_coord, range(1, 1 << 18))
             if all(F.pow(v, N18 // p) != 1 for p in (3, 7, 19, 73)))
    return g

@functools.cache
def full_log_table():
    g = generator()
    table = np.full(1 << 18, -1, dtype=np.int64)
    x = 1
    for e in range(N18):
        table[coord(x)] = e
        x = F.mul(x, g)
    return table

def log(v):
    """log of a nonzero element of F(2^18) (given in F(2^36) coordinates), or None if zero."""
    if v == 0:
        return None
    return int(full_log_table()[coord(v)])

def value(f, j, k):
    return C._value(f, j, k)

def t(j):
    return F.pow(F.zeta, j % M) ^ F.pow(F.zeta, (-j) % M)

def lines():
    """the 38 lines: (1, k) for k in 0..36, and (0, 1)."""
    return [(1, k) for k in range(M)] + [(0, 1)]

def line_logs(f):
    return {jk: log(value(f, *jk)) for jk in lines()}

def class_logs(f):
    return {jk: log(value(f, *jk)) for jk in characters()}

def log2(j):
    """k with 2^k = j mod 37."""
    x = 1
    for k in range(36):
        if x == j % M:
            return k
        x = 2 * x % M
    raise ValueError

if __name__ == '__main__':
    import time
    t0 = time.time()
    T = full_log_table()
    print('table built', time.time() - t0, 's; generator', generator())
    lt = log(t(1))
    print('log t_1 =', lt, 'mod 27:', lt % 27, 'mod 3:', lt % 3, 'ord =', N18 // np.gcd(lt, N18))
    l1 = log(1 ^ t(1))
    print('log(1+t_1) =', l1, 'mod 27:', l1 % 27, 'ord =', N18 // np.gcd(l1, N18))
    # check: t_j = t_1^(2^k_j)
    for j in (2, 3, 5, 6):
        assert log(t(j)) == (lt * pow(2, log2(j), N18)) % N18
    # N(t) = t^513 = t^3 (1+t)^4 ?
    tt = t(1)
    assert F.pow(tt, 513) == F.mul(F.pow(tt, 3), F.pow(1 ^ tt, 4))
    print('N(t) = t^3 (1+t)^4 holds')
