def base_t(v):
    l = log(v); assert l % 3 == 0; return (l // 3) * inv % ORD
chars = characters()
def d4orbit(v):
    a, b = v
    pts = {(s*p, u*q) for p, q in ((a, b), (b, a)) for s in (1, -1) for u in (1, -1)}
    half = sorted({w for w in pts if w > (0, 0)})
    return half
def orbit_reps(R):
    reps = []
    for a in range(0, R + 1):
        for b in range(0, a + 1):
            if math.gcd(a, b) == 1 and (a, b) != (0, 0):
                reps.append((a, b))
    return reps
MOD = 171
def exps(v):
    """e_v(c) = sum over w in half-orbit of 2^{k(w.c)} mod MOD, or None if some w.c = 0."""
    out = []
    for c in chars:
        s = 0
        for w in d4orbit(v):
            d = (w[0]*c[0] + w[1]*c[1]) % M
            if d == 0:
                s = None; break
            s += pow(2, log2(d), MOD)
        out.append(None if s is None else s % MOD)
    return out

def run(fid, R, maxk):
    f = T[fid]
    m = [base_t(value(f, *c)) % MOD if value(f, *c) else None for c in chars]
    reps = orbit_reps(R)
    E = {v: exps(v) for v in reps}
    hits = []
    for k in range(1, maxk + 1):
        for combo in itertools.combinations(reps, k):
            # classes usable: m not None and no orbit vanishes
            idx = [i for i in range(len(chars)) if m[i] is not None and all(E[v][i] is not None for v in combo)]
            if len(idx) < 8:
