See proposal.md (to be written).  condition(f, m) -> q."""
from __future__ import annotations
import functools, itertools, math, os, sys
_HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(_HERE, '..', 'tools'))
import halffrob
from halffrob import (ONE, pmul, preduce, pscale, pdiv, tfac, symmetries, _units, _half_orbit, _orbit_reps,
                      _psi, _sym_to_t, _rule90_powers, _strip, ord2, sord, _small_primes, _cldivmod)
from certificate import line_exponent, _pow2_log, _mobius

PRIME_BOUND = 20000
N_RADIUS = 2
MAX_N = 3
N_PSI = (3, 5)


@functools.cache
def _A(e: int, m: int):
    """A_e with Psi_e(t_j)^2 = t_j^{A_e} for j != 0, or None if some divisor e' > 1 of e is not +-2^a mod m
    or gcd(e', m) != 1."""
    logs = _pow2_log(m)
    divs = [d for d in range(1, e + 1) if e % d == 0]
    if any(d % m not in logs or math.gcd(d, m) != 1 for d in divs[1:]):
        return None
    return sum(_mobius(e // d) * 2 ** (logs[d % m] if d > 1 else 0) for d in divs)


def _pp(n, p):
    """p-adic valuation of n (n != 0)."""
    v = 0
    while n % p == 0:
        n //= p; v += 1
    return v


@functools.cache
def _natoms(group, m):
    """Atoms for N: (name, polynomial, half-orbit directions, kind, e)."""
    out = []
    for v in _orbit_reps(group, N_RADIUS):
        orbit, half = _half_orbit(v, group)
        P = ONE
        for w in half:
            P = pmul(P, tfac(w))
        out.append((('O', v), P, tuple(half), 'O', 1))
        for e in N_PSI:
            if math.gcd(e, m) != 1:
                continue
            P = ONE
            for w in half:
                term, power, T, i = frozenset(), ONE, _psi(e), 0
                while T >> i:
                    if T >> i & 1:
                        term = term ^ power
                    power = pmul(power, tfac(w))
                    i += 1
                P = pmul(P, term)
            out.append((('P%d' % e, v), P, tuple(half), 'P', e))
    return tuple(out)


def _unit_dirs(group, names, sign, alpha, beta):
    """Accumulate exponents: names like ('O', v) or ('P5', v); alpha[w] += sign per t_w, beta[(w,e)] += sign."""
    for name in names:
        kind, v = name
        _, half = _half_orbit(v, group)
        for w in half:
            if kind == 'O':
                alpha[w] = alpha.get(w, 0) + sign
            else:
                e = int(kind[1:])
                beta[(w, e)] = beta.get((w, e), 0) + sign


def score(f, m, r, unit_names, C, n_names, g, group):
    """The refined q_s (power in F(2^s)*) for a witness, as {p: k}."""
    s = sord(m)
    Ns = 2 ** s - 1
    Mg = Ns // (2 ** g - 1)
    r90 = _rule90_powers(m)
    primes = [p for p in _small_primes(PRIME_BOUND) if p > 2 and Mg % p == 0]
    if not unit_names and not n_names:
        return {p: _pp(Mg, p) for p in primes}
    alpha, beta = {}, {}
    _unit_dirs(group, unit_names, +1, alpha, beta)
    _unit_dirs(group, n_names, -1, alpha, beta)
    alphaU, betaU = {}, {}
    _unit_dirs(group, unit_names, +1, alphaU, betaU)
    # combined exponents E_w (squared convention) and separate non-representable Psi factors
    def exponents(al, be):
        E = {w: 2 * a for w, a in al.items()}
        sep = []
        for (w, e), b in be.items():
            if b == 0:
                continue
            A = _A(e, m)
            if A is None:
                sep.append(b)
            else:
                E[w] = E.get(w, 0) + b * A
        return E, sep
    E, sep = exponents(alpha, beta)
    out = {}
    for p in primes:
        kp = _pp(Mg, p)
        k90 = _pp(r90.get(p, 1), p)
        # general characters
        for w, ew in E.items():
            if ew != 0:
                kp = min(kp, k90 + _pp(ew, p))
        for b in sep:
            kp = min(kp, k90 + _pp(b, p))
        out[p] = kp
