    n_dirs = set()
    for name in n_names:
        _, half = _half_orbit(name[1], group)
        n_dirs |= set(half)
    EU, sepU = exponents(alphaU, betaU)
    logs = _pow2_log(m)
    for w0 in n_dirs:
        c0 = (w0[1], -w0[0])
        H = _sym_to_t([p_ * c0[0] + q_ * c0[1] for p_, q_ in C])
        if H is None:
            return {p: 0 for p in primes}
        if H == 0:
            continue
        AH = line_exponent(H, m)
        if AH is None:
            return {p: 0 for p in primes}
        total = AH
        seps = list(sepU)
        skip = False
        for w, ew in EU.items():
            if ew == 0:
                continue
            d = (w[0] * c0[0] + w[1] * c0[1]) % m
            if d == 0:
                if alphaU.get(w, 0) > 0:
                    skip = True  # t_0 = 0 kills lambda_f on this line
