                continue  # only Psi factors in w: Psi_e(0) = 1
            if d in logs:
                total += ew * 2 ** logs[d]
            else:
                seps.append(ew)
        if skip:
            continue
        for p in primes:
            kp = out[p]
            k90 = _pp(r90.get(p, 1), p)
            if total != 0:
                kp = min(kp, k90 + _pp(total, p))
            for b in seps:
                kp = min(kp, k90 + _pp(b, p))
            out[p] = kp
    return out


def _qs(sc):
    return math.prod(p ** k for p, k in sc.items())


def explain(f, m):
    f = frozenset(map(tuple, f))
    if m < 3 or m % 2 == 0 or not f or frozenset((-p, -q) for p, q in f) != f:
        return None
    s, d = sord(m), ord2(m)
    lift = (2 ** d - 1) // (2 ** s - 1)
    levels = [(g, pow(2, g, m)) for g in range(1, s) if s % g == 0]
    if not levels:
        return None
    group = symmetries(f)
    units = _units(group, m)
    natoms = _natoms(group, m)
    best = (1, None)

    def consider(r, unit_names, C, n_names, g, Bm):
        nonlocal best
        sc = score(f, m, r, unit_names, C, n_names, g, group)
        q = _qs(sc)
        if q > best[0]:
            best = (q, dict(r=r, units=list(unit_names), core=C, N=list(n_names), g=g, score=sc))

    fm = preduce(f, m)
    for g, n in levels:
        if all(((n * p) % m, (n * q) % m) in fm for p, q in fm):
            consider(1, [], f, [], g, fm)
    for r in (1, 2):
        Fr = pscale(f, r)
        C, stripped = _strip(Fr, units)
        if C == ONE:
            continue  # pure splitting: left to the other mechanisms
        Cm = preduce(C, m)

        def search(Bm, combo, start):
            for g, n in levels:
                if all(((n * p) % m, (n * q) % m) in Bm for p, q in Bm):
                    consider(r, stripped, C, combo, g, Bm)
            if len(combo) == MAX_N:
                return
            for i in range(start, len(natoms)):
                name, P, half, kind, e = natoms[i]
                search(preduce(pmul(Bm, P), m), combo + [name], i)

        search(Cm, [], 0)
    if best[0] == 1:
        return None
    w = best[1]
    w.update(q=best[0] * lift, q_s=best[0])
    return w


def condition(f, m: int) -> int:
    w = explain(f, m)
    return w['q'] if w else 1


if __name__ == '__main__':
    import json
    T = json.load(open(os.path.join(_HERE, '..', 'data', 'targets.json')))
    for t in T:
        f = frozenset(map(tuple, t['terms']))
        w = explain(f, 37)
        print(t['id'], None if w is None else {k: v for k, v in w.items() if k != 'core'})
