# ---------------------------------------------------------------- arithmetic

def _vp(n: int, p: int) -> int:
    n = abs(n)
    v = 0
    while n and n % p == 0:
        n //= p
        v += 1
    return v


@functools.cache
def _pow2_log(m: int) -> dict:
    """{r: a} with r = +-2^a mod m, the least such a."""
    out, x = {}, 1 % m
    for a in range(ord2(m)):
        out.setdefault(x, a)
        out.setdefault((-x) % m, a)
        x = 2 * x % m
    return out


def _mobius(n: int) -> int:
    out, p = 1, 2
    while p * p <= n:
        if n % p == 0:
            n //= p
            if n % p == 0:
                return 0
            out = -out
        p += 1
    return -out if n > 1 else out


@functools.cache
def _A(e: int, m: int):
    """A_e if e is representable at m (every divisor e' > 1 prime to m and +-2^a mod m), else None.
    For e = 1 (the unit 1 + X_w): 1."""
    if e == 1:
        return 1
    logs = _pow2_log(m)
    divs = [q for q in range(1, e + 1) if e % q == 0]
    if any(math.gcd(q, m) != 1 or q % m not in logs for q in divs[1:]):
        return None
    return sum(_mobius(e // q) * 2 ** (logs[q % m] if q > 1 else 0) for q in divs)


def _is_prime(n: int) -> bool:
    return n > 1 and all(n % p for p in range(2, int(n**0.5) + 1))


@functools.cache
def _primes_of_s(m: int):
    s = sord(m)
    Ns = 2**s - 1
    return tuple(p for p in _small_primes(PRIME_BOUND) if p > 2 and Ns % p == 0)


# ---------------------------------------------------------------- exponents of unit products

class _Book:
    """Exponent bookkeeping for a product of line units: E[w] (combined, representable) and
    sep[(w, e)] (non-representable, gcd(e, m) = 1 or e prime), per direction w (up to sign).
    Directions are stored as primitive vectors with the sign normalised."""

    def __init__(self, m):
        self.m = m
        self.E = {}
        self.sep = {}
        self.bad = False  # a unit whose values are not known to lie in <t_j>

    @staticmethod
    def _norm(w):
        a, b = w
        if a < 0 or (a == 0 and b < 0):
            a, b = -a, -b
        return (a, b)

    def add(self, w, e, k):
        """Phi_e(X_w)^k (e = 1: 1 + X_w; as a function this is a power of t_(w.c))."""
        if k == 0:
            return
        w = self._norm(w)
        A = _A(e, self.m)
        if A is not None:
            self.E[w] = self.E.get(w, 0) + k * A
        elif math.gcd(e, self.m) == 1 or _is_prime(e):
            self.sep[(w, e)] = self.sep.get((w, e), 0) + k
        else:
            self.bad = True

    def add_t(self, w, k):
        """t_w^k = X_w^-k (1 + X_w)^(2k)."""
        self.add(w, 1, 2 * k)

    def add_psi(self, w, e, k):
        """Psi_e(t_w)^k = (monomial) Phi_e(X_w)^k."""
        self.add(w, e, k)

    def power(self, p, k90, cap):
        """The largest k <= cap with p^k | q'_p E for every exponent."""
        if self.bad:
            return 0
        k = cap
        for ew in self.E.values():
            if ew != 0:
                k = min(k, k90 + _vp(ew, p))
        for b in self.sep.values():
            if b != 0:
                k = min(k, k90 + _vp(b, p))
        return k


# ---------------------------------------------------------------- Theorem A

def _theorem_a(f, m):
    """{p: k} from the exact factorisation f = monomial * line units * core, core = h^Q."""
    groups, core = unitpower.structure(f)
    book = _Book(m)
    for (w, e), (mults, npieces) in groups.items():
        ms = list(mults) + [0] * (npieces - len(mults))
        k = min(ms)
        if any(x != k for x in ms):
            # a partial product of the factors of Phi_e(X_w) is left in the core: no structure
            return {}
        book.add(w, e, k)
    out = {}
    if len(core) > 1:
        Q = unitpower._core_gcd(core)
        if Q <= 1:
            return {}
        Qs = [p for p in _primes_of_s(m) if Q % p == 0]
        # the core must be an exact Q'-th power for the prime powers claimed
    s = sord(m)
    Ns = 2**s - 1
    r90 = _rule90_powers(m)
    for p in _primes_of_s(m):
        cap = _vp(Ns, p)
        k = book.power(p, _vp(r90.get(p, 1), p), cap)
        if len(core) > 1:
            kq = _vp(Q, p)
            if kq == 0:
                k = 0
            else:
                k = min(k, kq)
                if k and not unitpower._core_root_ok(core, p**k):
                    k = 0
        if k:
            out[p] = k
    return out


# ---------------------------------------------------------------- Theorem B

def _fold(x, m, mask):
    while x >> m:
        x = (x & mask) ^ (x >> m)
    return x


class _Probe:
    """x^(p, r) -> z^(v1 p + v2 r) mod z^m - 1: a ring homomorphism commuting with dilations."""

    def __init__(self, v, m):
        self.v, self.m, self.mask = v, m, (1 << m) - 1

    def image(self, P):
        x = 0
        for p, r in P:
            x ^= 1 << ((self.v[0] * p + self.v[1] * r) % self.m)
        return x

    def mul(self, a, b):
        return _fold(_clmul(a, b), self.m, self.mask)

    def invariant(self, x, n):
        m = self.m
        y = 0
        i = 0
        while x >> i:
            if x >> i & 1:
                y |= 1 << (i * n % m)
            i += 1
        return y == x


def _dense(P, m):
    D = np.zeros((m, m), dtype=np.uint8)
    for p, r in P:
        D[p % m, r % m] ^= 1
    return D


def _dense_mul(A, B):
    C = np.fft.ifft2(np.fft.fft2(A.astype(np.float64)) * np.fft.fft2(B.astype(np.float64))).real
    return (np.rint(C).astype(np.int64) & 1).astype(np.uint8)


def _invariant(D, n, m) -> bool:
    idx = (np.arange(m) * n) % m
    return np.array_equal(D[np.ix_(idx, idx)], D)


@functools.cache
def _natoms(group, m):
    """Orbit units for N: (name, polynomial, half-orbit, kind, e)."""
    out = []
    for v in _orbit_reps(group, N_RADIUS):
        _, half = _half_orbit(v, group)
        P = ONE
        for w in half:
            P = pmul(P, tfac(w))
        out.append((("O", v), P, tuple(half), "O", 1))
        for e in N_PSI:
            if math.gcd(e, m) != 1:
                continue
            P = ONE
            for w in half:
                term, power, T, i = frozenset(), ONE, _psi(e), 0
                while T >> i:
                    if T >> i & 1:
                        term = term ^ power
                    power = pmul(power, tfac(w))
                    i += 1
                P = pmul(P, term)
            out.append((("P%d" % e, v), P, tuple(half), "P", e))
    return tuple(out)


def _line_H(C, w0):
    """C restricted to the line {c : w0.c = 0} = {k (w0_2, -w0_1)}, as H(t) (int bitmask), or None."""
    c0 = (w0[1], -w0[0])
    return _sym_to_t([p * c0[0] + q * c0[1] for p, q in C])


def _line_exponent(H, m):
    """A with H(t_j)^2 = t_j^A (j != 0) for H = t^i prod Psi_e^ke with representable e; None if not."""
    A = 0
    while H & 1 == 0:
        H >>= 1
        A += 2
    for e in range(3, 62, 2):
        if H == 1:
            break
        Ae = _A(e, m)
        if Ae is None:
            continue
        while True:
            q, rem = halffrob._cldivmod(H, _psi(e))
            if rem:
                break
            H, A = q, A + Ae
    return A if H == 1 else None


def _score_b(f, m, r, group, ugroups, C, n_names, g):
    """{p: k} for a Theorem-B witness: f^(r) = U * C with U given by ugroups {(w, e): k}, C the core,
    N the orbit units n_names, level g."""
    s = sord(m)
    Ns = 2**s - 1
    Mg = Ns // (2**g - 1)
    r90 = _rule90_powers(m)
    primes = [p for p in _primes_of_s(m) if Mg % p == 0]
    if not ugroups and not n_names:
        return {p: _vp(Mg, p) for p in primes}
    bookU = _Book(m)
    for (w, e), k in ugroups.items():
        bookU.add(w, e, k)
    book = _Book(m)
    for (w, e), k in ugroups.items():
        book.add(w, e, k)
    n_dirs = set()
    for name in n_names:
        kind, v = name
        _, half = _half_orbit(v, group)
        n_dirs |= set(half)
        for w in half:
            if kind == "O":
                book.add_t(w, -1)
            else:
                book.add_psi(w, int(kind[1:]), -1)
    out = {}
    for p in primes:
        k90 = _vp(r90.get(p, 1), p)
        out[p] = book.power(p, k90, _vp(Mg, p))
    if not n_names or all(k == 0 for k in out.values()):
        return out
    # lines where N vanishes: only the O-type directions vanish
    logs = _pow2_log(m)
    for name in n_names:
        kind, v = name
        if kind != "O":
            continue
        _, half = _half_orbit(v, group)
        for w0 in half:
            H = _line_H(C, w0)
            if H is None:
                return {}
            if H == 0:
                continue
            AH = _line_exponent(H, m)
            if AH is None:
                return {}
            c0 = (w0[1], -w0[0])
            total = AH
            seps = list(bookU.sep.values())
            dead = False
            for w, ew in bookU.E.items():
                if ew == 0:
                    continue
                dd = (w[0] * c0[0] + w[1] * c0[1]) % m
                if dd == 0:
                    # t_0 = 0: the unit vanishes on the whole line unless it is a pure Psi product
                    if any(e == 1 and k > 0 for (w2, e), k in ugroups.items() if w2 == w):
                        dead = True
                        break
                    continue
                if dd in logs:
                    total += ew * 2 ** logs[dd]
                else:
                    seps.append(ew)
            if dead:
                continue
            for p in primes:
                k90 = _vp(r90.get(p, 1), p)
                k = out[p]
                if total != 0:
                    k = min(k, k90 + _vp(total, p))
                for b in seps:
                    if b:
                        k = min(k, k90 + _vp(b, p))
                out[p] = k
    return out


def _theorem_b(f, m):
    """The best {p: k} over Theorem-B witnesses, with the witness."""
    s = sord(m)
    levels = [(g, pow(2, g, m)) for g in range(1, s) if s % g == 0]
    if not levels:
        return {}, None
    group = symmetries(f)
    groups, core = unitpower.structure(f)
    ugroups = {}
    for (w, e), (mults, npieces) in groups.items():
        ms = list(mults) + [0] * (npieces - len(mults))
        k = min(ms)
        if any(x != k for x in ms):
            return {}, None  # a partial cyclotomic factor: not a unit, not a core we can use
        ugroups[(w, e)] = k
    natoms = _natoms(group, m)
    probes = [_Probe(v, m) for v in PROBES]
    best = [1, {}, None]

    def consider(r, C, n_names, g):
        sc = _score_b(f, m, r, group, ugroups, C, n_names, g)
        q = math.prod(p**k for p, k in sc.items())
        if q > best[0]:
            best[:] = [q, sc, dict(r=r, N=list(n_names), g=g, core=C, units=ugroups)]

    # pure case on f itself (also covers non-symmetric-looking supports)
    fm = preduce(f, m)
    for g, n in levels:
        if all(((n * p) % m, (n * q) % m) in fm for p, q in fm):
            consider(1, f, [], g)
    for r in (1, 2):
        Cr = pscale(core, r)
        if Cr == ONE:
            continue
        imgs = [P.image(Cr) for P in probes]
        atom_imgs = [[P.image(a[1]) for P in probes] for a in natoms]

        def search(imgs, combo, start):
            for g, n in levels:
                if all(P.invariant(x, n) for P, x in zip(probes, imgs)):
                    # verify exactly
                    D = _dense(Cr, m)
                    for i in combo:
                        D = _dense_mul(D, _dense(natoms[i][1], m))
                    if _invariant(D, n, m):
                        consider(r, Cr, [natoms[i][0] for i in combo], g)
            if len(combo) == MAX_N:
                return
            for i in range(start, len(natoms)):
                search([P.mul(x, a) for P, x, a in zip(probes, imgs, atom_imgs[i])], combo + [i], i)

        search(imgs, [], 0)
    return best[1], best[2]


# ---------------------------------------------------------------- the condition

def _dilation(f):
    """(p, h) with f = h(x^p, y^p) for the largest such p > 1, or None."""
    g = 0
    for a, b in f:
        g = math.gcd(g, math.gcd(abs(a), abs(b)))
    if g <= 1:
        return None
    return g, frozenset((a // g, b // g) for a, b in f)


def explain(f, m: int):
    f = frozenset(map(tuple, f))
    if m < 3 or m % 2 == 0 or not f:
        return None
    symmetric = frozenset((-p, -q) for p, q in f) == f
    if not symmetric:
        return None
    s, d = sord(m), ord2(m)
    Ns = 2**s - 1
    R = (2**d - 1) // Ns
    found = []
    q_s = 1
    sa = _theorem_a(f, m)
    sb, wb = _theorem_b(f, m)
    for p in _primes_of_s(m):
        k = max(sa.get(p, 0), sb.get(p, 0))
        if k:
            q_s *= p**k
    if sa:
        found.append(("units times a power", sa))
    if sb:
        found.append(("half-Frobenius", sb, {k: v for k, v in wb.items() if k != "core"}))
    q = q_s * R
    dil = _dilation(f)
    if dil is not None:
        p, h = dil
        g = math.gcd(p, m)
        if g > 1:
            # f = h(x^g, y^g): eigenvalues of f at m are those of h at m/g (zeta^g primitive)
            h = frozenset((a * (p // g), b * (p // g)) for a, b in h)
            m2 = m // g
            if m2 > 1:
                q2 = condition(h, m2)
                d2 = ord2(m2)
                lift = (2**d - 1) // (2**d2 - 1)
                q = math.lcm(q, q2 * lift)
                found.append(("dilation", g, q2))
    if USE_PREVIOUS:
        q = math.lcm(q, certificate.condition(f, m), unitpower.condition(f, m))
    if q == R or q == 1:
        return None
    return dict(q=q, found=found)


def condition(f, m: int) -> int:
    w = explain(f, m)
    return w["q"] if w else 1


