"""Certificates for Lean `linear_combination`: for a Laurent identity L = R over GF(2) in x, y, with
xi = 1/x, yi = 1/y, find integer polynomials c1, c2, c3 with
    L - R = c1 * 2 + c2 * (x*xi - 1) + c3 * (y*yi - 1)      in Z[x, xi, y, yi].
Then `linear_combination c1 * h2 + c2 * hx + c3 * hy` proves L = R from h2 : (2:R) = 0,
hx : x * xi = 1, hy : y * yi = 1.

Usage: import and call certificate(L, R) with sympy expressions in x, xi, y, yi.
"""
import sympy as sp

x, xi, y, yi = sp.symbols('x xi y yi')


def reduce_pair(P, u, ui):
    """Reduce P modulo (u*ui - 1): returns (remainder with no monomial containing both u and ui, quotient)."""
    P = sp.Poly(sp.expand(P), x, xi, y, yi)
    rem = 0
    quot = 0
    for monom, coeff in P.terms():
        a, b, c, d = monom
        term = {x: a, xi: b, y: c, yi: d}
        eu, eui = term[u], term[ui]
        k = min(eu, eui)
        if k == 0:
            rem += coeff * x**a * xi**b * y**c * yi**d
            continue
        term[u] -= k
        term[ui] -= k
        base = coeff * x**term[x] * xi**term[xi] * y**term[y] * yi**term[yi]
        rem += base
        # u^k ui^k - 1 = (u ui - 1) * sum_{i<k} (u ui)^i
        quot += base * sum((u * ui)**i for i in range(k))
    return sp.expand(rem), sp.expand(quot)


def certificate(L, R):
    D = sp.expand(L - R)
    rem, c2 = reduce_pair(D, x, xi)
    rem, c3 = reduce_pair(rem, y, yi)
    P = sp.Poly(rem, x, xi, y, yi)
    for monom, coeff in P.terms():
        assert coeff % 2 == 0, (monom, coeff)
    c1 = sp.expand(rem / 2)
    assert sp.expand(D - (2 * c1 + c2 * (x * xi - 1) + c3 * (y * yi - 1))) == 0
    return c1, c2, c3


def lean(expr):
    s = sp.sstr(sp.expand(expr))
    return s.replace('**', '^')


def poly_of_offsets(pts):
    out = 0
    for a, b in pts:
        out += (x**a if a >= 0 else xi**(-a)) * (y**b if b >= 0 else yi**(-b))
    return sp.expand(out)


def lean_poly_of_offsets(pts):
    terms = []
    for a, b in sorted(pts):
        f = []
        if a > 0:
            f.append('x^%d' % a if a > 1 else 'x')
        elif a < 0:
            f.append('xi^%d' % -a if a < -1 else 'xi')
        if b > 0:
            f.append('y^%d' % b if b > 1 else 'y')
        elif b < 0:
            f.append('yi^%d' % -b if b < -1 else 'yi')
        terms.append('*'.join(f) if f else '1')
    return ' + '.join(terms)

